"use client";
/* Bolt, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Bolt(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("bolt"); }, []);
  return React.createElement("piix-sprite", { "name": "bolt", ...piixAttrs(props) });
}

export default Bolt;
